import argparse
from pathlib import Path
import numpy as np
import pandas as pd
from tqdm import tqdm
from .common import load_metadata
import warnings

warnings.warn(
    "r6.baseline is deprecated. Neutral-pose calibration is "
    "generated by the R5 calibration pipeline. R6 should consume "
    "driver_baselines_r5.csv instead.",
    DeprecationWarning,
    stacklevel=2
)
def build_baselines(metadata_csv, output_dir, fps=15, seconds=30, min_frames=None):
    df = load_metadata(metadata_csv)
    output_dir = Path(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)
    required_frames = int(round(fps * seconds))
    if min_frames is None:
        min_frames = required_frames

    rows, rejected = [], []
    # Use only alert-labelled recordings. Sort paths for deterministic collection.
    for subject_id, group in tqdm(df[df.label == "alert"].groupby("subject_id"), desc="Neutral calibration"):
        collected_pitch, collected_yaw, sources = [], [], []
        for _, rec in group.sort_values("npz_path").iterrows():
            p = Path(rec.npz_path)
            if not p.exists():
                rejected.append({"subject_id": subject_id, "npz_path": str(p), "reason": "missing_file"})
                continue
            try:
                with np.load(p, allow_pickle=False) as z:
                    if not {"head_pose", "face_detected"}.issubset(z.files):
                        rejected.append({"subject_id": subject_id, "npz_path": str(p), "reason": "missing_pose_or_detection"})
                        continue
                    pose = np.asarray(z["head_pose"], dtype=np.float64)
                    detected = np.asarray(z["face_detected"]).reshape(-1).astype(bool)
                    if pose.ndim != 2 or pose.shape[1] != 3 or len(pose) != len(detected):
                        rejected.append({"subject_id": subject_id, "npz_path": str(p), "reason": "invalid_shapes"})
                        continue
                    valid = detected & np.isfinite(pose[:, 0]) & np.isfinite(pose[:, 1])
                    # Only the first valid normal frames are used, capped at 30 seconds.
                    remaining = required_frames - len(collected_pitch)
                    if remaining <= 0:
                        break
                    idx = np.flatnonzero(valid)[:remaining]
                    if len(idx):
                        collected_pitch.extend(pose[idx, 0].tolist())
                        collected_yaw.extend(pose[idx, 1].tolist())
                        sources.append(str(p))
            except Exception as exc:
                rejected.append({"subject_id": subject_id, "npz_path": str(p), "reason": f"read_error:{exc}"})
            if len(collected_pitch) >= required_frames:
                break

        if len(collected_pitch) < min_frames:
            rejected.append({
                "subject_id": subject_id,
                "reason": "insufficient_valid_normal_frames",
                "valid_frames": len(collected_pitch),
                "required_frames": min_frames,
            })
            continue

        pitch = np.asarray(collected_pitch[:required_frames], dtype=np.float64)
        yaw = np.asarray(collected_yaw[:required_frames], dtype=np.float64)
        rows.append({
            "subject_id": subject_id,
            "mean_pitch": float(np.mean(pitch)),
            "mean_yaw": float(np.mean(yaw)),
            "std_pitch": float(np.std(pitch, ddof=1)) if len(pitch) > 1 else 0.0,
            "std_yaw": float(np.std(yaw, ddof=1)) if len(yaw) > 1 else 0.0,
            "calibration_frames_used": int(len(pitch)),
            "calibration_seconds": float(len(pitch) / fps),
            "calibration_fps": int(fps),
            "source_clip_count": len(sources),
            "source_npz_files": ";".join(sources),
        })

    out = pd.DataFrame(rows)
    # The first four columns are the exact agreed R5 interface.
    ordered = ["subject_id", "mean_pitch", "mean_yaw", "std_pitch",
               "std_yaw", "calibration_frames_used", "calibration_seconds",
               "calibration_fps", "source_clip_count", "source_npz_files"]
    if len(out):
        out = out[ordered]
    else:
        out = pd.DataFrame(columns=ordered)
    out.to_csv(output_dir / "driver_baselines.csv", index=False)
    pd.DataFrame(rejected).to_csv(output_dir / "baseline_rejections.csv", index=False)
    print(f"Saved {len(out)} driver baselines to {output_dir/'driver_baselines.csv'}")
    print(f"Required valid normal frames per driver: {required_frames} ({seconds}s at {fps} FPS)")
    if len(out) == 0:
        print("WARNING: no baseline was generated. Check that alert-labelled R3 NPZ files exist and contain enough face-detected frames.")
    return out

def main():
    ap = argparse.ArgumentParser(description="R6 30-second neutral-pose calibration")
    ap.add_argument("--metadata", required=True, help="R3 rldd_metadata_index.csv")
    ap.add_argument("--output", default="outputs")
    ap.add_argument("--fps", type=int, default=15)
    ap.add_argument("--seconds", type=int, default=30)
    ap.add_argument("--min-frames", type=int, default=None)
    a = ap.parse_args()
    build_baselines(a.metadata, a.output, a.fps, a.seconds, a.min_frames)

if __name__ == "__main__":
    main()
